/**
 * sarithIndex.js — the exact index [PGL₂(ℤ[1/p]) : Γ] by coset enumeration.
 *
 * Λ = PGL₂(ℤ[1/p]) acts on the tree T_{p+1} with one orbit of vertices and of
 * edges, and w = (0 1; p 0) inverts the edge [o, o′ = w·o]. By Bass–Serre,
 *     Λ = Λ_o ∗_{Λ_e} Λ_m,   Λ_o = PGL₂(ℤ),  Λ_e = Γ₀(p)± (the stabilizer of
 *     the line ⟨(1, 0)⟩ in P¹(F_p)),  Λ_m = Λ_e ⋊ ⟨w⟩,
 * so Λ is generated by the reflections a, b, c of PGL₂(ℤ) (modularIndex.js)
 * and the involution w, with the relators (ab)², (bc)³ and w s w = φ(s) for
 * Schreier generators s of Λ_e, φ(s) = w s w⁻¹ ∈ Λ_e written in a, b, c.
 *
 * An element g of Λ is written in these letters by walking back along the
 * tree: if g·o ≠ o, the first step from o towards g·o is the line spanned by
 * the columns of g mod p; with h ∈ PGL₂(ℤ) taking ⟨(1, 0)⟩ to that line,
 * (h w)⁻¹ g moves o one step less. Every word is multiplied out again and
 * compared with its matrix before it is used.
 *
 * A coset table that closes is re-verified (modularIndex.js), and then
 * [Λ : Γ] is exactly its size; one that hits its limits claims nothing.
 */
import { coxeterWord, enumerateInvolutions } from './modularIndex.js';

const babs = (x) => (x < 0n ? -x : x);
const bgcd = (a, b) => { a = babs(a); b = babs(b); while (b) [a, b] = [b, a % b]; return a; };
const mul = (A, B) => [A[0] * B[0] + A[1] * B[2], A[0] * B[1] + A[1] * B[3], A[2] * B[0] + A[3] * B[2], A[2] * B[1] + A[3] * B[3]];
const adj = (A) => [A[3], -A[1], -A[2], A[0]];
const det = (A) => A[0] * A[3] - A[1] * A[2];
const mod = (x, p) => ((x % p) + p) % p;
function primitive(A) {
    const g = A.reduce((s, x) => bgcd(s, x), 0n);
    return g > 1n ? A.map((x) => x / g) : A.slice();
}
const projEq = (A, B) => {
    // A ∝ B: all 2×2 minors of the pair of vectors vanish
    for (let i = 0; i < 4; i++) for (let j = i + 1; j < 4; j++) if (A[i] * B[j] !== A[j] * B[i]) return false;
    return true;
};
function inverseMod(a, p) {
    let [r0, r1, s0, s1] = [mod(a, p), p, 1n, 0n];
    while (r1) { const q = r0 / r1; [r0, r1] = [r1, r0 - q * r1]; [s0, s1] = [s1, s0 - q * s1]; }
    if (r0 !== 1n) throw new Error('not invertible mod p');
    return mod(s0, p);
}
/** p-adic valuation of a nonzero BigInt. */
function vp(x, p) { let v = 0; x = babs(x); while (x % p === 0n) { x /= p; v++; } return v; }

const COXETER = [[-1n, 0n, 0n, 1n], [0n, 1n, 1n, 0n], [-1n, 1n, 0n, 1n]];
const COXETER_RELATORS = [[0, 1, 0, 1], [1, 2, 1, 2, 1, 2]];
const reverse = (w) => w.slice().reverse();          // the inverse of a word in involutions

/**
 * The presentation of PGL₂(ℤ[1/S]) for a list of primes S: letters 0, 1, 2 are
 * a, b, c and letter 3 + i is w_{S[i]} = (0 1; S[i] 0). Built one prime at a
 * time: Λ_{S∪{q}} = Λ_S ∗_{Λ_S ∩ Γ₀(q)±} ⟨Λ_S ∩ Γ₀(q)±, w_q⟩, since Λ_{S∪{q}}
 * acts on T_{q+1} with vertex stabilizer Λ_S, transitively on the edges
 * (Λ_S ⊇ PGL₂(ℤ) is transitive on P¹(F_q)), and w_q inverts an edge.
 * Returns { primes, gens, relators }.
 */
export function presentationPGL2ZS(primesIn) {
    const primes = (Array.isArray(primesIn) ? primesIn : [primesIn]).map(BigInt);
    const P = { primes: [], gens: COXETER.slice(), relators: COXETER_RELATORS.slice() };
    for (const q of primes) {
        const Wq = [0n, 1n, q, 0n];
        const letter = P.gens.length;
        // the action of the current generators on P¹(F_q): t ↔ ⟨(t, 1)⟩ for t < q, q ↔ ⟨(1, 0)⟩
        const point = (v) => (mod(v[1], q) === 0n ? q : mod(v[0] * inverseMod(v[1], q), q));
        const vec = (t) => (t === q ? [1n, 0n] : [t, 1n]);
        const act = (G, t) => { const v = vec(t); return point([G[0] * v[0] + G[1] * v[1], G[2] * v[0] + G[3] * v[1]]); };
        const base = q;
        const word = new Map([[base, []]]), queue = [base];
        while (queue.length) {
            const t = queue.shift();
            for (let g = 0; g < letter; g++) {
                const s2 = act(P.gens[g], t);
                if (!word.has(s2)) { word.set(s2, [g].concat(word.get(t))); queue.push(s2); }
            }
        }
        if (word.size !== Number(q) + 1) throw new Error(`not transitive on P¹(F_${q})`);
        const wordMat = (w) => w.reduce((M, x) => mul(M, P.gens[x]), [1n, 0n, 0n, 1n]);
        const schreier = [], seen = new Set();
        for (const [t, ut] of word) {
            for (let g = 0; g < letter; g++) {
                const sw = reduceInvolutions(reverse(word.get(act(P.gens[g], t))).concat([g], ut));
                if (!sw.length) continue;
                const key = sw.join(',');
                if (seen.has(key)) continue;
                seen.add(key);
                const S = wordMat(sw);
                if (act(S, base) !== base) throw new Error('internal: a Schreier generator moves the base point');
                schreier.push({ sw, S });
            }
        }
        // a small generating set of Λ_e suffices for the relators w s w = φ(s). Elements with small
        // entries come first, so that s and φ(s) = w s w⁻¹ are short words: T, J, the earlier D_p, and
        // V_k = (k, −(1 + kk′)/q; q, −k′) with kk′ ≡ −1 (mod q) (Rademacher's generators of Γ₀(q));
        // the Schreier generators after them. Added shortest first until coset enumeration in Λ_{S'}
        // gives index q + 1 (they lie in Λ_e, of that index). For q = 61 after 2 this takes the
        // relators from 7488 letters in all (the longest 750) to 474; coset enumeration in the result
        // runs 2–30× faster on groups with a prime 13, and S = {73, 79} no longer needs words of
        // tens of thousands of continued-fraction steps.
        const small = [[1n, 1n, 0n, 1n], [-1n, 0n, 0n, 1n], ...P.primes.map((p) => [p, 0n, 0n, 1n])];
        for (let k = 1n; k < q; k++) {
            const kp = mod(-inverseMod(k, q), q);
            small.push([k, -(1n + k * kp) / q, q, -kp]);
        }
        const smallItems = [];
        for (const S of small) {
            if (act(S, base) !== base) continue;
            let sw;
            try { sw = wordInPGL2ZS(S, P); } catch (e) { continue; }
            if (sw.length) smallItems.push({ sw, S });
        }
        smallItems.sort((x, y) => x.sw.length - y.sw.length);
        schreier.sort((x, y) => x.sw.length - y.sw.length);
        schreier.unshift(...smallItems);
        let chosen = schreier;
        const want = Number(q) + 1;
        for (let k = 1; k <= schreier.length; k++) {
            const sub = schreier.slice(0, k);
            const r = enumerateInvolutions(letter, P.relators, sub.map((x) => x.sw), { maxCosets: 20000, seconds: 1, strategy: 'felsch' });
            if (r.index === want) { chosen = sub; break; }
        }
        // the edge group Λ_e on its generators, and φ(s) = w s w⁻¹ as words in the letters before w
        const phiWords = chosen.map(({ S }) => wordInPGL2ZS(primitive(mul(mul(Wq, S), adj(Wq))), P));
        const relators = chosen.map(({ sw }, k) => [letter].concat(sw, [letter], reverse(phiWords[k])));
        (P.levels = P.levels || []).push({ q, letter, relCount: P.relators.length, egens: chosen.map((x) => x.sw), ephi: phiWords });
        P.primes.push(q);
        P.gens.push(Wq);
        P.relators.push(...relators);
    }
    return P;
}

function reduceInvolutions(w) {
    const out = [];
    for (const x of w) { if (out.length && out[out.length - 1] === x) out.pop(); else out.push(x); }
    return out;
}

/**
 * g ∈ PGL₂(ℤ[1/S]) (an integer matrix, projectively) as a word in the letters
 * of P; throws if g is not in the group. Each w_q fixes the standard vertex of
 * every other tree, so the trees are emptied one prime at a time.
 */
export function wordInPGL2ZS(M0, P) {
    let M = primitive(M0.map(BigInt));
    const word = [];
    let d = det(M);
    if (d === 0n) throw new Error('singular');
    let rest = babs(d);
    for (const p of P.primes) while (rest % p === 0n) rest /= p;
    if (rest !== 1n) throw new Error(`not in PGL₂(ℤ[1/${P.primes.join(',') || '1'}]): det ${d}`);
    P.primes.forEach((p, i) => {
        const letter = 3 + i;
        for (let k = vp(det(M), p); k > 0; k--) {
            // the first step from o towards M·o in T_p: the column space of M mod p
            const col = mod(M[0], p) || mod(M[2], p) ? [M[0], M[2]] : [M[1], M[3]];
            const h = mod(col[0], p) ? [1n, 0n, mod(col[1] * inverseMod(col[0], p), p), 1n] : [0n, 1n, 1n, 0n];
            word.push(...coxeterWord(h), letter);
            const next = primitive(mul(mul(adj(P.gens[letter]), adj(h)), M));
            if (vp(det(next), p) !== k - 1) throw new Error('internal: the walk did not shorten');
            M = next;
        }
    });
    word.push(...coxeterWord(M));
    const W = reduceInvolutions(word);
    const back = W.reduce((A, x) => mul(A, P.gens[x]), [1n, 0n, 0n, 1n]);
    if (!projEq(back, M0.map(BigInt))) throw new Error('internal: the word does not give the matrix');
    return W;
}

/**
 * [PGL₂(ℤ[1/S]) : ⟨mats⟩] for integer matrices whose determinants are ± products of primes in S.
 * Returns { index } or { limit } (or { error } if a matrix is not in the group).
 */
export function indexInPGL2ZS(mats, S, opts = {}) {
    const P = presentationPGL2ZS(S);
    let words;
    try { words = mats.map((m) => wordInPGL2ZS(m, P)); } catch (e) { return { error: e.message }; }
    const r = enumerateInvolutions(P.gens.length, P.relators, words, opts);
    return { ...r, words, relators: P.relators.length };
}

/**
 * The exact step of the Presentation Calculator, over ℚ, for generators given
 * by rational entries (strings) and the primes S where Γ is unbounded.
 *
 * At a prime ℓ ∉ S where some determinant has odd valuation, Γ is bounded but
 * contains an inversion: it fixes the midpoint of an edge at the standard
 * vertex, and the elements of even valuation fix both ends. So the kernel K
 * of the parities χ: Γ → (ℤ/2)^B (B: those primes) is Γ ∩ PGL₂(ℤ[1/S]), of
 * index |χ(Γ)|, with Schreier generators u_c g u_{c+χ(g)}⁻¹. Then
 * [PGL₂(ℤ[1/S]) : K] by coset enumeration; finite ⟺ Γ is S-arithmetic.
 * At a prime ℓ ∉ S with even but positive valuations, Γ fixes a vertex other
 * than the standard one, and is conjugated to fix o (commonFixedVertex).
 *
 * Returns null when this does not apply, else
 *   { index | limit | error, S, kernelIndex, ms }   (index = [PGL₂(ℤ[1/S]) : K]).
 */
export function exactIndexCheck(rows, Sin, { seconds = 2, maxCosets = 1000000 } = {}) {
    if (!Sin.length) return null;
    const R = reduceToLambda(rows, Sin);
    if (!R) return null;
    const t0 = Date.now();
    const r = indexInPGL2ZS(R.kernelGens, R.S, { seconds, maxCosets });
    return { index: r.index ?? null, limit: r.limit ?? null, error: r.error ?? null, S: R.S.map(String), kernelIndex: R.reps.size, bad: R.bad.map(String), conjugatedAt: R.conjugatedAt, ms: Date.now() - t0 };
}

/**
 * The reduction of exactIndexCheck, on its own: Γ = ⟨rows⟩ ⊂ PGL₂(ℚ) bounded at every prime outside
 * S. Returns null when it does not apply, else { S, mats (the generators, primitive), bad (primes
 * with odd valuations), parity(M), reps (Map: parity key → { c, M } with M ∈ Γ), kernelGens
 * (Schreier generators of K, conjugated by C), C (the conjugator: kernelGens = C⁻¹·(…)·C),
 * conjugatedAt }.
 */
export function reduceToLambda(rows, Sin) {
    const S = Sin.map(BigInt);
    // primitive integer matrices
    const mats = [];
    for (const row of rows) {
        const q = row.map((e) => /^\s*(-?\d+)\s*(?:\/\s*(\d+))?\s*$/.exec(String(e)));
        if (q.some((x) => !x)) return null;
        const num = q.map((x) => BigInt(x[1])), den = q.map((x) => BigInt(x[2] || '1'));
        const L = den.reduce((l, d) => (l / bgcd(l, d)) * d, 1n);
        mats.push(primitive(num.map((n, i) => n * (L / den[i]))));
    }
    // bad primes: dividing a determinant, outside S
    const bad = [];
    for (const M of mats) {
        let d = babs(det(M));
        for (const p of S) while (d % p === 0n) d /= p;
        for (let f = 2n; f * f <= d; f++) while (d % f === 0n) { if (!bad.includes(f)) bad.push(f); d /= f; }
        if (d > 1n && !bad.includes(d)) bad.push(d);
    }
    // primes where every valuation is even: Γ fixes a vertex there, conjugated to o below
    const evenBad = bad.filter((l) => mats.every((M) => !(vp(det(M), l) & 1)));
    const oddBad = bad.filter((l) => !evenBad.includes(l));
    bad.length = 0; bad.push(...oddBad);
    const parity = (M) => bad.map((l) => vp(det(M), l) & 1);
    // a transversal of K in Γ: words for the parity classes reached
    const key = (c) => c.join('');
    const reps = new Map([[key(bad.map(() => 0)), { c: bad.map(() => 0), M: [1n, 0n, 0n, 1n] }]]);
    const queue = [...reps.values()];
    while (queue.length) {
        const r = queue.shift();
        for (const G of mats) {
            const c = r.c.map((x, i) => x ^ parity(G)[i]);
            if (!reps.has(key(c))) { const n = { c, M: primitive(mul(r.M, G)) }; reps.set(key(c), n); queue.push(n); }
        }
    }
    const gens = [];
    for (const r of reps.values()) for (const G of mats) {
        const c = r.c.map((x, i) => x ^ parity(G)[i]);
        const U = reps.get(key(c)).M;
        const sch = primitive(mul(mul(r.M, G), adj(U)));
        if (bad.some((l) => vp(det(sch), l) % 2)) return null;                // internal: K has even valuations
        gens.push(sch);
    }
    // at each prime ℓ with even valuations, conjugate a common fixed vertex to o; also at a prime with
    // odd valuations whose inverted edge is not at o (K fixes both its ends, not o)
    const conj = [];
    let C = [1n, 0n, 0n, 1n];
    for (const l of [...evenBad, ...bad.filter((l) => gens.some((M) => vp(det(M), l) !== 0))]) {
        const c = commonFixedVertex(gens, l);
        if (!c) return null;
        const ci = adj(c);
        for (let i = 0; i < gens.length; i++) gens[i] = primitive(mul(mul(ci, gens[i]), c));
        if (gens.some((M) => vp(det(M), l) !== 0)) return null;               // internal: not fixed
        C = primitive(mul(C, c));
        conj.push(String(l));
    }
    return { S, mats, bad, parity, key, reps, kernelGens: gens, C, conjugatedAt: conj };
}

/**
 * A vertex of T_ℓ fixed by every matrix of a bounded group, as c with the
 * vertex c·o (c a product of GL₂(ℤ) matrices and (0 1; ℓ 0), so c fixes the
 * standard vertex at every other prime). Alternating projections: the
 * projection of c·o onto Fix(g) is the midpoint of [c·o, g·c·o], reached by
 * walking half of the way, as in wordInPGL2ZS. Returns null if it does not settle.
 */
export function commonFixedVertex(mats, l0) {
    const l = BigInt(l0), Wl = [0n, 1n, l, 0n];
    let c = [1n, 0n, 0n, 1n];
    for (let round = 0; round < 64; round++) {
        let moved = false;
        for (const M of mats) {
            let g = primitive(mul(mul(adj(c), M), c));                       // g in the frame of c·o
            const d = vp(det(g), l);
            if (d === 0) continue;
            if (d % 2) return null;                                          // an inversion: not this case
            // walk d/2 steps from o towards g·o
            for (let k = 0; k < d / 2; k++) {
                const col = mod(g[0], l) || mod(g[2], l) ? [g[0], g[2]] : [g[1], g[3]];
                const h = mod(col[0], l) ? [1n, 0n, mod(col[1] * inverseMod(col[0], l), l), 1n] : [0n, 1n, 1n, 0n];
                const step = mul(h, Wl);
                c = primitive(mul(c, step));
                g = primitive(mul(mul(adj(step), g), step));
            }
            moved = true;
        }
        if (!moved) return c;
    }
    return null;
}
